<?php
if(!defined('ABSPATH'))exit;
add_action('add_meta_boxes',function(){add_meta_box('eicr_service_images','Service page image gallery','eicr_service_images_box','eicr_service','normal','default');});
function eicr_service_images_box($post){wp_nonce_field('eicr_service_images','eicr_service_images_nonce');echo '<p>Add up to three working images. The Featured Image is used as the main service image.</p><div class="eicr-image-fields" style="display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:16px">';for($i=1;$i<=3;$i++){$id=absint(get_post_meta($post->ID,'_eicr_gallery_'.$i,true));$url=$id?wp_get_attachment_image_url($id,'medium'):'';echo '<div class="eicr-image-field" style="border:1px solid #dcdcde;padding:12px;background:#fff"><div class="eicr-image-preview" style="aspect-ratio:4/3;background:#f6f7f7;display:grid;place-items:center;overflow:hidden">'.($url?'<img src="'.esc_url($url).'" style="width:100%;height:100%;object-fit:cover">':'<span>No image selected</span>').'</div><input type="hidden" name="eicr_gallery_'.$i.'" value="'.esc_attr($id).'"><p><button type="button" class="button eicr-pick-image">Choose image</button> <button type="button" class="button-link-delete eicr-remove-image">Remove</button></p></div>';}echo '</div>';}
add_action('save_post_eicr_service',function($id){if(!isset($_POST['eicr_service_images_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['eicr_service_images_nonce'])),'eicr_service_images')||!current_user_can('edit_post',$id))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;for($i=1;$i<=3;$i++)update_post_meta($id,'_eicr_gallery_'.$i,absint($_POST['eicr_gallery_'.$i]??0));});
add_action('admin_enqueue_scripts',function($hook){$screen=get_current_screen();if(!$screen||$screen->post_type!=='eicr_service')return;wp_enqueue_media();wp_enqueue_script('jquery');$js=<<<'JS'
jQuery(function($){$(document).on('click','.eicr-pick-image',function(e){e.preventDefault();var field=$(this).closest('.eicr-image-field'),frame=wp.media({title:'Choose service image',button:{text:'Use this image'},multiple:false});frame.on('select',function(){var a=frame.state().get('selection').first().toJSON();field.find('input[type=hidden]').val(a.id);field.find('.eicr-image-preview').html('<img src="'+(a.sizes&&a.sizes.medium?a.sizes.medium.url:a.url)+'" style="width:100%;height:100%;object-fit:cover">')});frame.open()});$(document).on('click','.eicr-remove-image',function(e){e.preventDefault();var field=$(this).closest('.eicr-image-field');field.find('input[type=hidden]').val('');field.find('.eicr-image-preview').html('<span>No image selected</span>')})});
JS;wp_add_inline_script('jquery',$js);});
function eicr_service_image_urls($post_id){$urls=[];for($i=1;$i<=3;$i++){$id=absint(get_post_meta($post_id,'_eicr_gallery_'.$i,true));if($id){$url=wp_get_attachment_image_url($id,'large');if($url)$urls[]=$url;}}return $urls;}
